export const ALL_EMOJI: Emoji[] = EMOJI_CATEGORIES.flatMap((c) => c.items)

/** Substring match over the Unicode name. Bounded — a picker never needs more
 *  than a screenful, and an unbounded filter over 1500 entries on every
 *  keystroke is the kind of thing that makes a search box feel cheap. */
export function searchEmoji(q: string, limit = 60): Emoji[] {
  const t = q.trim().toLowerCase()
  if (!t) return []
  const out: Emoji[] = []
  for (const item of ALL_EMOJI) {
    if (item.k.includes(t)) {
      out.push(item)
      if (out.length >= limit) break
    }
  }
  return out
}
